const categoryScript="\nconst by=id=>document.getElementById(id);\nconst make=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};\nconst repo='/repos/duykhang68/khoahoctienghan',path='src/data/knowledge-navigation.json';\nlet snap=null,rows=[],busy=false,dragId=null;\nconst changed=()=>snap&&rows.map(x=>x.id).join(',')!==snap.rows.map(x=>x.id).join(',');\nfunction sync(){by('cat-save').disabled=busy||!changed()||!by('cat-confirm').checked;by('cat-reset').disabled=busy||!changed();by('cat-refresh').disabled=busy;}\nfunction move(id,to){if(busy)return;const from=rows.findIndex(x=>x.id===id);if(from<0||to<0||to>=rows.length||from===to)return;const [row]=rows.splice(from,1);rows.splice(to,0,row);render(id);by('cat-position').textContent=row.title+' · Vị trí '+(to+1)+' / '+rows.length;}\nfunction render(focus){const list=by('cat-list');list.replaceChildren();rows.forEach((row,i)=>{const li=make('li');li.className='category-row';li.draggable=!busy;li.dataset.id=row.id;const title=make('div');title.append(make('strong',String(i+1).padStart(2,'0')+' · '+row.title),make('small','/'+row.id+'/'));const controls=make('div');controls.className='category-controls';for(const [d,label] of [[-1,'Lên'],[1,'Xuống']]){const btn=make('button',d===-1?'↑':'↓');btn.type='button';btn.dataset.dir=String(d);btn.setAttribute('aria-label',label+' '+row.title);btn.disabled=busy||i+d<0||i+d>=rows.length;btn.addEventListener('click',()=>move(row.id,i+d));controls.append(btn)}li.append(title,controls);li.addEventListener('dragstart',e=>{if(busy)return;dragId=row.id;e.dataTransfer.setData('text/plain',row.id);e.dataTransfer.effectAllowed='move'});li.addEventListener('dragend',()=>{dragId=null});li.addEventListener('dragover',e=>{if(dragId&&!busy){e.preventDefault();e.dataTransfer.dropEffect='move'}});li.addEventListener('drop',e=>{e.preventDefault();if(dragId){const id=dragId;dragId=null;move(id,i)}});list.append(li)});if(focus){const li=[...list.children].find(x=>x.dataset.id===focus);li?.querySelector('button:not(:disabled)')?.focus({preventScroll:true})}sync();}\nasync function refresh(){if(busy)return;if(changed()&&!confirm('Bỏ thứ tự chưa gửi để tải lại?'))return;busy=true;sync();try{const res=await fetch('/admin/api/categories/',{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(16000)});if(!res.ok)throw Error('upstream');const data=await res.json();if(!/^[a-f0-9]{40}$/.test(data.sha)||!Array.isArray(data.rows)||!data.rows.length||new Set(data.rows.map(x=>x.id)).size!==data.rows.length||!data.rows.every(x=>/^[a-z0-9-]+$/.test(x.id)&&typeof x.title==='string'))throw Error('invalid');snap=data;rows=data.rows.map(x=>({...x}));by('cat-status').textContent='SHA production: '+data.sha;by('cat-confirm').checked=false;by('cat-result').textContent='';}catch{by('cat-status').textContent='Không tải được thứ tự production. '+(snap?'Giữ dữ liệu trước.':'Thử lại.')}finally{busy=false;render();}}\nasync function submit(){if(busy||!changed()||!by('cat-confirm').checked)return;const token=by('cat-token').value.trim();by('cat-token').value='';const result=by('cat-result');if(!token.startsWith('github'+'_pat_')){result.textContent='Cần fine-grained PAT hợp lệ.';return}busy=true;const order=rows.map(x=>x.id);render();result.textContent='Kiểm tra phiên bản…';try{\n const request=async(path,method='GET',body)=>{const res=await fetch('https://api.github.com'+path,{method,redirect:'error',cache:'no-store',credentials:'omit',headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(!res.ok)throw Error('GitHub HTTP '+res.status);return res.json()};\n const user=await request('/user'),repository=await request(repo);if(user.login!=='duykhang68'||repository.full_name!=='duykhang68/khoahoctienghan'||repository.permissions?.push!==true)throw Error('Chỉ chủ repo có quyền gửi PR.');\n const main=(await request(repo+'/git/ref/heads/main')).object.sha;if(main!==snap.sha)throw Error('Main đã đổi hoặc chưa phát hành. Tải lại production.');\n const base=await request(repo+'/git/commits/'+main);const tree=await request(repo+'/git/trees','POST',{base_tree:base.tree.sha,tree:[{path,mode:'100644',type:'blob',content:JSON.stringify(order,null,2)+'\\n'}]});\n const commit=await request(repo+'/git/commits','POST',{message:'ui: reorder approved Knowledge Base categories',tree:tree.sha,parents:[main]});\n if((await request(repo+'/git/ref/heads/main')).object.sha!==main)throw Error('Main vừa đổi; không tạo nhánh.');\n const branch='review/category-order-'+crypto.randomUUID().slice(0,12);await request(repo+'/git/refs','POST',{ref:'refs/heads/'+branch,sha:commit.sha});\n const pr=await request(repo+'/pulls','POST',{title:'ui: reorder approved Knowledge Base categories',head:branch,base:'main',draft:true,body:'Only approved category order. No route, topic ID, content or Tech Blog taxonomy changes. Review diff and native CI; do not auto-merge. Snapshot '+main});\n const u=new URL(pr.html_url);if(u.origin!=='https://github.com'||!/^\\/duykhang68\\/khoahoctienghan\\/pull\\/\\d+$/.test(u.pathname))throw Error('Kiểm tra PR đã gửi trên GitHub.');\n const link=make('a','Mở PR nháp #'+pr.number);link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';result.replaceChildren(make('span','Đã đề nghị thay đổi; chưa xuất bản. '),link);by('cat-confirm').checked=false;\n }catch(e){result.textContent=e.message+' · Kiểm tra GitHub trước khi gửi lại.'}finally{busy=false;render();}}\nby('cat-confirm').addEventListener('change',sync);by('cat-reset').addEventListener('click',()=>{if(!snap||busy)return;rows=snap.rows.map(x=>({...x}));by('cat-confirm').checked=false;by('cat-position').textContent='Đã khôi phục.';render()});by('cat-refresh').addEventListener('click',refresh);by('cat-save').addEventListener('click',submit);void refresh();\n";
const pipelineMarkup="<div class=\"sheet-blog\"><header class=\"sb-header\"><div><span class=\"sb-kicker\">EDITORIAL STUDIO · P1.8</span><h1>Publication Pipeline</h1><p>Theo dõi toàn bộ bài đã gửi vào FIFO, không kể nguồn tạo bài. Không thay đổi hàng đợi hay tự merge.</p><p><a href=\"/admin/\">Trung tâm quản trị</a> · <a href=\"/admin/editor/\">Editor V2</a> · <a href=\"/admin/sheets/\">Google Sheets VN</a></p></div></header><section class=\"sb-progress-section\" data-queue-progress aria-labelledby=\"sb-progress-heading\"><header class=\"sb-progress-heading\"><div><span class=\"sb-kicker\">PUBLICATION PIPELINE · FIFO</span><h2 id=\"sb-progress-heading\">Thanh Tiến độ</h2><p>Issue được tiếp nhận theo số tăng dần; kiểm tra chi tiết CI/CD ở đầu hàng đợi.</p></div><button type=\"button\" data-progress-refresh>Cập nhật tiến độ</button></header><div class=\"sb-progress-summary\"><div><span>Đang chờ / xử lý</span><strong data-progress-queued>—</strong></div><div><span>Đã gửi · chờ Issue (thiết bị)</span><strong data-progress-sent>0</strong></div><div><span>Đã xác minh</span><strong data-progress-done>—</strong></div></div><p class=\"sb-progress-status\" data-progress-status role=\"status\" aria-live=\"polite\">Chưa cập nhật</p><div data-progress-cards></div><p class=\"sb-progress-note\">6 mốc hoàn thành, không phải ETA. Chỉ 100% khi Issue đã đóng với marker VERIFIED đủ bằng chứng. HEAD/base không khớp PR hiện tại thì không tính CI PASS. Sheet writeback tách riêng. Chỉ đọc GitHub công khai; cập nhật khi vào trang và bằng nút thủ công.</p></section></div>";
