 const header=styles+'<div class="dm-shell"><nav class="dm-nav" aria-label="Điều hướng"><a href="'+lesson+'">← Soạn bài</a><a href="'+course+'curriculum/">Giáo trình</a><a href="/admin/courses/">Course Studio</a></nav><header class="dm-hero"><div><span class="dm-kicker">P2.5 · MEDIA STUDIO</span><h1>Thư viện Video &amp; Audio</h1><p>'+esc(courseTitle)+' · '+esc(lessonTitle)+'</p><div class="dm-actions">'+(driveId.test(folder||'')?link('https://drive.google.com/drive/folders/'+folder,'Mở thư mục Drive',true,true):'')+link(base,'Cập nhật dữ liệu')+link(lesson+'quiz/','Quiz Builder')+'</div></div><aside class="dm-connection"><span class="dm-kicker">GOOGLE DRIVE</span><strong>'+(online?'Đã kết nối · Chỉ đọc':'Chưa kết nối')+'</strong><p>Chỉ quản trị viên có quyền truy cập. Không xóa file gốc khi bỏ liên kết.</p></aside></header>';
 const metrics='<section aria-label="Tổng quan media"><div class="dm-stats">'+stat('File hỗ trợ',online?rows.length:'—','Trong danh sách Drive')+stat('Video',online?countType('video'):'—','Video hợp lệ')+stat('Audio',online?countType('audio'):'—','Audio hợp lệ')+stat('Đã gắn',linked.size+' / 30','Liên kết của bài học')+'</div></section>';
