 return header+metrics+notice+'<div class="dm-toolbar"><label>Tìm media<input id="dm-search" type="search" placeholder="Tên file video hoặc audio"></label><label>Loại media<select id="dm-type"><option value="all">Tất cả</option><option value="video">Video</option><option value="audio">Audio</option><option value="unknown">Chưa xác minh</option></select></label><label>Liên kết<select id="dm-association"><option value="all">Tất cả</option><option value="linked">Đã gắn</option><option value="unlinked">Chưa gắn</option></select></label><button class="dm-btn" type="button" id="dm-reset">Đặt lại</button></div><p id="dm-count" class="dm-muted" role="status"></p><section aria-label="Media đã gắn"><div class="dm-section-head"><h2>Đã gắn vào bài học</h2><span class="dm-muted">'+linked.size+' / 30</span></div>'+(linked.size?'<div class="dm-list">'+attached.map(f=>card(f,true)).join('')+missingCards+'</div>':'<div class="dm-empty">Chưa có media liên kết.</div>')+'</section><section aria-label="Thư viện chưa gắn"><div class="dm-section-head"><h2>Media trong thư viện</h2><span class="dm-muted">'+(online?unattached.length+' file chưa gắn':'Chưa tải được')+'</span></div>'+(unattached.length?'<div class="dm-list">'+unattached.map(f=>card(f,false)).join('')+'</div>':'<div class="dm-empty">'+(online?'Không có video/audio chưa gắn trong danh sách hiện tại.':'Thử cập nhật sau khi khôi phục kết nối Drive.')+'</div>')+'</section><p id="dm-empty-filter" class="dm-notice" hidden>Không tìm thấy media phù hợp.</p><script nonce="'+nonce+'">('+mediaStudioBrowser.toString()+')();</script></div>';
